def norm_shape(S):
 S=np.array(list(S)); mn=S.min(0); return frozenset(map(tuple,S-mn))
def transforms(S):
 out=[]
 for k in range(4):
  a=np.array(list(S)); a=np.column_stack([a[:,1],-a[:,0]]) if False else a
 # coords transform manually dihedral
 for refl in [False,True]:
  for k in range(4):
   pts=[]
   for r,c in S:
    if refl:c=-c
    for _ in range(k):r,c=c,-r
    pts.append((r,c))
   out.append(norm_shape(pts))
 return set(out)
